<script module lang="ts">
/**
 * Tree.Node: one item of the tree: its row and, when it is an open branch, the rows under it.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */

import { Icon, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/tree.module.css'
import Spinner from './Spinner.svelte'
import TreeNode from './TreeNode.svelte'
import type { TreeItem, TreeMessages } from './Tree.svelte'

export interface TreeNodeProps {
  item: TreeItem
  /**
   * The level it sits at: 0 at the top.
   */
  level: number
  /**
   * The open branches by id.
   */
  open: ReadonlySet<string>
  /**
   * The selected item's id.
   */
  selected: string | null
  messages: TreeMessages
}
</script>

<script lang="ts">
let { item, level, open, selected, messages }: TreeNodeProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
const under = $derived(item.children ?? [])
const branch = $derived(under.length > 0 || item.hasChildren === true)
const disabled = $derived(item.disabled === true)
const expanded = $derived(branch && !disabled && open.has(item.id))
const loading = $derived(item.loading === true)
const hasMore = $derived(item.hasMore === true)
const chosen = $derived(!disabled && selected === item.id)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<li
    class={styles.item}
    role="treeitem"
    aria-labelledby={`${uid}-label`}
    aria-describedby={item.description === undefined ? undefined : `${uid}-description`}
    aria-expanded={branch ? expanded : undefined}
    aria-selected={disabled ? undefined : chosen}
    aria-disabled={(disabled) ? true : undefined}
    aria-busy={(expanded && loading) ? true : undefined}
    data-tree-item={item.id}
    data-selected={(chosen) ? '' : undefined}
    data-disabled={(disabled) ? '' : undefined}
    ><div class={styles.row} style:--pm-tree-level={level} data-tree-part="row"
      >{#if branch
        }<span class={styles.toggle} data-tree-part="toggle" aria-hidden="true"
          ><span class={styles.chevron}><Icon name="next" size="sm" /></span
        ></span
      >{:else
        }<span class={styles.slot}></span
      >{/if
      }<span class={styles.text}
        ><span class={styles.label} id={`${uid}-label`}>{item.label}</span
        >{#if item.description !== undefined
          }<span class={styles.description} id={`${uid}-description`}>{item.description}</span
        >{/if
      }</span
    ></div
    >{#if expanded && (under.length > 0 || loading || hasMore)
      }<ul class={styles.group} role="group"
        >{#each under as child (child.id)
          }<TreeNode item={child} level={level + 1} {open} {selected} {messages}
        />{/each
        }{#if hasMore
          }<li
            class={styles.item}
            role="treeitem"
            aria-labelledby={`${uid}-more`}
            aria-selected="false"
            aria-busy={(loading) ? true : undefined}
            data-tree-part="more"
            ><div
              class={styles.row}
              style:--pm-tree-level={level + 1}
              data-tree-part="row"
              data-busy={(loading) ? '' : undefined}
              ><span class={styles.slot}
                >{#if loading}<Spinner size="sm" label={messages.loading} />{/if
              }</span
              ><span class={styles.text}
                ><span class={styles.more} id={`${uid}-more`}
                  >{(loading) ? messages.loading : messages.loadMore
                }</span
              ></span
            ></div
          ></li
        >{:else if loading
          }<li class={styles.item} role="none"
            ><div class={styles.row} style:--pm-tree-level={level + 1} data-busy=""
              ><span class={styles.slot}><Spinner size="sm" label={messages.loading} /></span
              ><span class={styles.text}
                ><span class={styles.status} aria-hidden="true">{messages.loading}</span
              ></span
            ></div
          ></li
        >{/if
      }</ul
    >{/if
  }</li
>{/if
}{@render joined.end?.()}
